{"charges": [{"claim": "Changing slice start from lastIndex to 0 causes duplicate-slash normalization to incorrectly process earlier parts of the pathname when multiple protocol-like patterns appear, breaking URLs like 'http://example.com/foo//bar/http://example.com//baz/http://test.com//qux'", "file": "index.js", "line": 169, "severity": "major", "witnessCode": "import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('normalizeUrl duplicate slash handling', () => {
  it('should correctly normalize path with multiple protocol-like patterns', () => {
    const input = 'http://example.com/foo//bar/http://example.com//baz/http://test.com//qux';
    const expected = 'http://example.com/foo/bar/http://example.com/baz/http://test.com/qux';
    const actual = normalizeUrl(input);
    assert.strictEqual(actual, expected);
  });
});"}]}
